import type { EngineInterface, Register } from 'claude-code'

// Runs the mod's own bin/afferent every 6 hours, and when the person types /afferent.
// Repo updates stay quiet (they are in ~/.cache/afferent.log). Signals, the things a
// person should act on, show as one toast, and the same signals toast only once.
export const runCommand = (root: string) => ['bash', `${root}/bin/afferent`]

const HOUR = 60 * 60 * 1000
export const PERIOD_MS = 6 * HOUR
export const RUN_TIMEOUT_MS = 10 * 60 * 1000

// The period counts from the last run that worked, so a failed run is tried again at the next hourly check.
// A session claims a run before it starts it; other sessions wait until the claim is older than the longest run.
export const isDue = (lastSuccess: number | null, claimedAt: number | null, now: number) =>
  (lastSuccess === null || now - lastSuccess >= PERIOD_MS) && (claimedAt === null || now - claimedAt >= RUN_TIMEOUT_MS)

// A run that found another run holding the lock prints "busy:" and did no work.
export const didWork = (exitCode: number, stdout: string) => exitCode === 0 && !stdout.startsWith('busy:')

export type Report = { updated: string[]; skipped: string[]; rules: string[]; tools: string[]; merged: string[] }

// Reads the script's lines: "updated <repo>: +3", "skip <repo>: <reason>", "rules <repo>: <files>",
// "tools <tool>: <what to do>" and "merged <repo>: <branches>". The rest is ignored.
export function parseReport(stdout: string): Report {
  const lines = stdout.split('\n')
  const after = (tag: string) => lines.filter(l => l.startsWith(tag)).map(l => l.slice(tag.length))
  return {
    updated: after('updated '),
    skipped: after('skip '),
    rules: after('rules '),
    tools: after('tools '),
    merged: after('merged '),
  }
}

// One line for the toast, or undefined when there is nothing to act on.
export function signalText({ rules, tools, merged }: Report): string | undefined {
  const parts = [
    ...rules.map(r => `📜 rules changed: ${r}`),
    ...tools.map(t => `🔧 ${t}`),
    ...(merged.length > 0 ? [`✓ merged, safe to clean up: ${merged.join('; ')}`] : []),
  ]
  return parts.length === 0 ? undefined : `afferent · ${parts.join(' · ')}`
}

// The full report for /afferent.
export function reportText(report: Report): string {
  const section = (title: string, items: string[]) => (items.length === 0 ? [] : [title, ...items.map(i => `  ${i}`)])
  const lines = [
    ...section('Rules changed (read before your next task):', report.rules),
    ...section('Tools to update:', report.tools),
    ...section('Merged branches (clean up per the post-merge hygiene SOP):', report.merged),
    ...section('Updated:', report.updated),
    ...section('Left alone:', report.skipped),
  ]
  return lines.length === 0 ? 'afferent: all repos up to date, nothing to act on.' : lines.join('\n')
}

// One run at a time in this session; the script's own lock covers other sessions.
let isRunning = false

// Runs the script once and records the result. Answers the report, or why there is none.
async function run($: EngineInterface): Promise<string> {
  if (isRunning) return 'afferent: a run is already going.'
  isRunning = true
  try {
    await $.store.set('claimedAt', await $.clock.now())
    const { exitCode, stdout } = await $.process.run(runCommand($.plugin.root), { timeoutMs: RUN_TIMEOUT_MS })
    if (!didWork(exitCode, stdout)) {
      return exitCode === 0 ? 'afferent: another run is going.' : 'afferent: the run failed; see ~/.cache/afferent.log.'
    }
    await $.store.set('lastSuccess', await $.clock.now())
    const report = parseReport(stdout)
    const signals = signalText(report)
    if (signals !== undefined && signals !== (await $.store.get('lastTold'))) $.ui.toast(signals, { timeoutMs: 20_000 })
    await $.store.set('lastTold', signals ?? '')
    return reportText(report)
  } finally {
    isRunning = false
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // A -p run or the SDK may exit in the middle of a run.
    if (!e.isInteractive) return next(e)
    await $.command.register({ name: 'afferent', description: 'Update ~/projects now and show what to act on' })
    const get = async (key: string) => ((await $.store.get(key)) ?? null) as number | null
    const tick = async () => {
      if (!isRunning && isDue(await get('lastSuccess'), await get('claimedAt'), await $.clock.now())) await run($)
    }
    void tick()
    $.clock.every(HOUR, () => void tick())
    return next(e)
  })

  on('command.run', { command: 'afferent' }, async $ => ({ text: await run($) }))
}

